    private async Task LoadData()
    {
        isLoading = true;
        await ProductionPlanService.SyncAllPlanStatusesAsync();
        
        var allPlans = await ProductionPlanService.GetAllProductionPlansAsync();
        dbDemands = allPlans.Where(p => p.Status == ProductionPlanStatus.Demand).ToList();
        productionPlans = allPlans.Where(p => p.Status != ProductionPlanStatus.Demand).ToList();
        
        productsList = await ProductService.GetAllActiveProductsAsync();
        machinesList = await MachineService.GetAllActiveMachinesAsync();

        isLoading = false;
    }

    private void SyncCalendarState()
    {
        weekDays.Clear();
        int diff = (7 + (currentCalendarDate.DayOfWeek - DayOfWeek.Monday)) % 7;
        currentMonday = currentCalendarDate.AddDays(-1 * diff).Date;
        for (int i = 0; i < 7; i++)
        {
            weekDays.Add(currentMonday.AddDays(i));
        }

        monthDays.Clear();
        var firstDayOfMonth = new DateTime(currentCalendarDate.Year, currentCalendarDate.Month, 1);
        int offset = (7 + (firstDayOfMonth.DayOfWeek - DayOfWeek.Monday)) % 7;
        var gridStart = firstDayOfMonth.AddDays(-offset);
        for (int i = 0; i < 42; i++)
        {
            monthDays.Add(gridStart.AddDays(i));
        }
    }

    private void ChangeViewMode(CalendarViewMode newMode)
    {
        currentViewMode = newMode;
        SyncCalendarState();
    }

    private void NavigateToMonthFromYear(int month)
    {
        currentCalendarDate = new DateTime(currentCalendarDate.Year, month, 1);
        currentViewMode = CalendarViewMode.Month;
        SyncCalendarState();
    }

    private void NavigateToWeekFromMonth(DateTime day)
    {
        currentCalendarDate = day;
        currentViewMode = CalendarViewMode.Week;
        SyncCalendarState();
    }

    private void OnDatePickerChanged(ChangeEventArgs e)
    {
        if (DateTime.TryParse(e.Value?.ToString(), out var parsedDate))
        {
            currentCalendarDate = parsedDate;
            SyncCalendarState();
        }
    }

    private void GoToToday()
    {
        currentCalendarDate = DateTime.Today;
        SyncCalendarState();
    }

    private void PreviousPeriod()
    {
        if (currentViewMode == CalendarViewMode.Week)
            currentCalendarDate = currentCalendarDate.AddDays(-7);
        else if (currentViewMode == CalendarViewMode.Month)
            currentCalendarDate = currentCalendarDate.AddMonths(-1);
        else
            currentCalendarDate = currentCalendarDate.AddYears(-1);

        SyncCalendarState();
    }

    private void NextPeriod()
    {
        if (currentViewMode == CalendarViewMode.Week)
            currentCalendarDate = currentCalendarDate.AddDays(7);
        else if (currentViewMode == CalendarViewMode.Month)
            currentCalendarDate = currentCalendarDate.AddMonths(1);
        else
            currentCalendarDate = currentCalendarDate.AddYears(1);

        SyncCalendarState();
    }

    private List<ProductionPlan> GetPlansForDayAndHour(DateTime day, int hour)
    {
        var slotStart = day.Date.AddHours(hour);
        var slotEnd = day.Date.AddHours(hour + 1);
        return productionPlans.Where(p =>
            p.PlannedStartDate < slotEnd &&
            p.PlannedEndDate > slotStart
        ).ToList();
    }


