    private void ToggleProductSelection(int productId, bool isSelected)
    {
        if (isSelected && !selectedProductIds.Contains(productId))
        {
            selectedProductIds.Add(productId);
        }
        else if (!isSelected && selectedProductIds.Contains(productId))
        {
            selectedProductIds.Remove(productId);
        }
    }

    private void ToggleMachineSelection(int machineId, bool isSelected)
    {
        if (isSelected && !selectedMachineIds.Contains(machineId))
        {
            selectedMachineIds.Add(machineId);
        }
        else if (!isSelected && selectedMachineIds.Contains(machineId))
        {
            selectedMachineIds.Remove(machineId);
        }
    }

    private int GetCalculatedCapacity()
    {
        var productId = selectedProductIds.FirstOrDefault();
        if (productId == 0) return 0;
        var product = productsList.FirstOrDefault(p => p.Id == productId);
        if (product == null) return 0;

        double totalCapacity = 0;
        foreach (var machineId in selectedMachineIds)
        {
            var mach = machinesList.FirstOrDefault(m => m.Id == machineId);
            if (mach != null)
            {
                double machineCapacity = 0;
                if (mach is CoilWindingMachine cwm)
                {
                    var originalProduct = cwm.CurrentProduct;
                    cwm.CurrentProduct = product;
                    var speed = cwm.CalculateOptimalSpeed(SpeedStrategyFactory);
                    cwm.CurrentProduct = originalProduct; // restore
                    machineCapacity = speed > 0 ? (speed * 60) : 50;
                }
                else
                {
                    machineCapacity = 30; // standard fallback
                }
                totalCapacity += machineCapacity;
            }
        }

        int finalQuantity = (int)totalCapacity;
        if (finalQuantity <= 0) finalQuantity = 1;

        if (isPlanningFromDemand && draggedDemandPlan != null)
        {
            finalQuantity = Math.Min(finalQuantity, draggedDemandPlan.TargetQuantity);
        }

        return finalQuantity;
    }

    private bool IsMachineBusy(int machineId)
    {
        var slotStart = plannedStartDate;
        var slotEnd = isPlanningFromDemand ? plannedStartDate.AddHours(1) : plannedEndDate;

        return productionPlans
            .Where(p => p.Id != (editingPlanId ?? 0))
            .Where(p => p.Status != ProductionPlanStatus.Demand)
            .Where(p => p.PlannedStartDate < slotEnd && p.PlannedEndDate > slotStart)
            .SelectMany(p => p.PlanMachines.Select(pm => pm.Machine?.Id))
            .Any(id => id == machineId);
    }

    private async Task SavePlan()
    {
        if (string.IsNullOrWhiteSpace(planCode))
        {
            errorMessage = "Lütfen kod girin.";
            return;
        }

        isSaving = true;
        errorMessage = null;
        successMessage = null;

        // Geçmiş zamanlı planlama kontrolü
        if (planStatus != ProductionPlanStatus.Demand && !isCreatingDemand && !isEditingDemand)
        {
            var currentHourStart = DateTime.Now.Date.AddHours(DateTime.Now.Hour);
            if (plannedStartDate < currentHourStart)
            {
                var isNewOrScheduled = false;
                if (editingPlanId == null)
                {
                    isNewOrScheduled = true;
                }
                else
                {
                    var existing = productionPlans.FirstOrDefault(p => p.Id == editingPlanId.Value);
                    if (existing != null && (existing.Status == ProductionPlanStatus.Scheduled || existing.Status == ProductionPlanStatus.Demand))
                    {
                        isNewOrScheduled = true;
                    }
                }

                if (isNewOrScheduled)
                {
                    errorMessage = "Geçmiş zamanlı planlama yapılamaz.";
                    isSaving = false;
                    return;
                }
            }
        }

        try
        {
            if (isPlanningFromDemand || isEditing)
            {
                var slotStart = plannedStartDate;
                var slotEnd = isPlanningFromDemand ? plannedStartDate.AddHours(1) : plannedEndDate;

                var busyMachineIds = productionPlans
                    .Where(p => p.Id != (editingPlanId ?? 0))
                    .Where(p => p.Status != ProductionPlanStatus.Demand)
                    .Where(p => p.PlannedStartDate < slotEnd && p.PlannedEndDate > slotStart)
                    .SelectMany(p => p.PlanMachines.Select(pm => pm.Machine?.Id))
                    .Where(id => id.HasValue)
                    .Select(id => id!.Value)
                    .ToHashSet();

                var overlappingMachineNames = machinesList
                    .Where(m => selectedMachineIds.Contains(m.Id))
                    .Where(m => busyMachineIds.Contains(m.Id))
                    .Select(m => m.Name)
                    .ToList();

                if (overlappingMachineNames.Any())
                {
                    errorMessage = $"Seçilen şu makine(ler) bu zaman aralığında zaten başka bir plana atanmıştır: {string.Join(", ", overlappingMachineNames)}";
                    isSaving = false;
                    return;
                }
            }

            if (isPlanningFromDemand)
            {
                if (!selectedMachineIds.Any())
                {
                    errorMessage = "Lütfen en az bir makine seçin.";
                    isSaving = false;
                    return;
                }

                var product = productsList.FirstOrDefault(p => selectedProductIds.Contains(p.Id));
                if (product == null)
                {
                    errorMessage = "Ürün bulunamadı.";
                    isSaving = false;
                    return;
                }

                var plan = new ProductionPlan
                {
                    PlanCode = planCode,
                    Description = description,
                    PlannedStartDate = plannedStartDate,
                    PlannedEndDate = plannedStartDate.AddHours(1),
                    Status = ProductionPlanStatus.Scheduled,
                    TargetQuantity = GetCalculatedCapacity(),
                    CreatedDate = DateTime.Now,
                    UpdatedDate = DateTime.Now
                };

                plan.PlanProducts.Add(new ProductionPlanProduct
                {
                    Product = product,
                    CreatedDate = DateTime.Now,
                    UpdatedDate = DateTime.Now
                });

                foreach (var id in selectedMachineIds)
                {
                    var machine = machinesList.FirstOrDefault(m => m.Id == id);
                    if (machine != null)
                    {
                        plan.PlanMachines.Add(new ProductionPlanMachine
                        {
                            Machine = machine,
                            CreatedDate = DateTime.Now,
                            UpdatedDate = DateTime.Now
                        });
                    }
                }

                await ProductionPlanService.SaveProductionPlanAsync(plan);

                if (draggedDemandPlan != null)
                {
                    draggedDemandPlan.TargetQuantity -= plan.TargetQuantity;
                    if (draggedDemandPlan.TargetQuantity <= 0)
                    {
                        await ProductionPlanService.DeleteProductionPlanAsync(draggedDemandPlan.Id);
                    }
                    else
                    {
                        await ProductionPlanService.SaveProductionPlanAsync(draggedDemandPlan);
                    }
                }

                isPlanningFromDemand = false;
                draggedDemandPlan = null;
            }
            else if (isCreatingDemand || isEditingDemand)
            {
                if (selectedDemandProductId == 0)
                {
                    errorMessage = "Lütfen bir ürün seçin.";
                    isSaving = false;
                    return;
                }

                var product = productsList.FirstOrDefault(p => p.Id == selectedDemandProductId);
                if (product == null)
                {
                    errorMessage = "Ürün bulunamadı.";
                    isSaving = false;
                    return;
                }

                var plan = new ProductionPlan
                {
                    Id = editingPlanId ?? 0,
                    PlanCode = planCode,
                    Description = description,
                    PlannedStartDate = DateTime.MinValue,
                    PlannedEndDate = DateTime.MinValue,
                    Status = ProductionPlanStatus.Demand,
                    TargetQuantity = targetQuantity,
                    CreatedDate = DateTime.Now,
                    UpdatedDate = DateTime.Now
                };

                plan.PlanProducts.Add(new ProductionPlanProduct
                {
                    Product = product,
                    CreatedDate = DateTime.Now,
                    UpdatedDate = DateTime.Now
                });

                await ProductionPlanService.SaveProductionPlanAsync(plan);
            }
            else
            {
                var plan = new ProductionPlan
                {
                    Id = editingPlanId ?? 0,
                    PlanCode = planCode,
                    Description = description,
                    PlannedStartDate = plannedStartDate,
                    PlannedEndDate = plannedEndDate,
                    Status = planStatus,
                    TargetQuantity = GetCalculatedCapacity(),
                    CreatedDate = DateTime.Now,
                    UpdatedDate = DateTime.Now
                };

                foreach (var id in selectedProductIds)
                {
                    var product = productsList.FirstOrDefault(p => p.Id == id);
                    if (product != null)
                    {
                        plan.PlanProducts.Add(new ProductionPlanProduct
                        {
                            Product = product,
                            CreatedDate = DateTime.Now,
                            UpdatedDate = DateTime.Now
                        });
                    }
                }

                foreach (var id in selectedMachineIds)
                {
                    var machine = machinesList.FirstOrDefault(m => m.Id == id);
                    if (machine != null)
                    {
                        plan.PlanMachines.Add(new ProductionPlanMachine
                        {
                            Machine = machine,
                            CreatedDate = DateTime.Now,
                            UpdatedDate = DateTime.Now
                        });
                    }
                }

                await ProductionPlanService.SaveProductionPlanAsync(plan);
            }

            showModal = false;
            await LoadData();
        }
        catch (Exception ex)
        {
            errorMessage = $"Kaydedilirken hata oluştu: {ex.Message}";
        }
        finally
        {
            isSaving = false;
        }
    }

    private async Task DeletePlan()
    {
        if (editingPlanId.HasValue)
        {
            isSaving = true;
            try
            {
                await ProductionPlanService.DeleteProductionPlanAsync(editingPlanId.Value);
                showModal = false;
                await LoadData();
            }
            catch (Exception ex)
            {
                errorMessage = $"Silinirken hata oluştu: {ex.Message}";
            }
            finally
            {
                isSaving = false;
            }
        }
    }

    private async Task DeleteDemand(int id)
    {
        try
        {
            await ProductionPlanService.DeleteProductionPlanAsync(id);
            await LoadData();
        }
        catch (Exception ex)
        {
            errorMessage = $"Talep silinirken hata oluştu: {ex.Message}";
        }
    }

    private string GetPlanStatusLabel(ProductionPlanStatus status) => status switch
    {
        ProductionPlanStatus.Demand => "Talep",
        ProductionPlanStatus.Scheduled => "Planlandı",
        ProductionPlanStatus.InProgress => "Üretimde",
        ProductionPlanStatus.Completed => "Tamamlandı",
        ProductionPlanStatus.NotCompleted => "Tamamlanamadı",
        ProductionPlanStatus.Awaiting => "Bekleniyor",
        _ => "Bilinmeyen"
    };

    private string GetPlanCardStyle(ProductionPlan plan)
    {
        int hash = plan.PlanCode.GetHashCode();
        int hue = Math.Abs(hash % 360);
        return $"--plan-hue: {hue};";
    }

    private string GetPlanTooltip(ProductionPlan plan)
    {
        var productNames = string.Join(", ", plan.PlanProducts.Select(p => p.Product != null ? p.Product.Name : "Urun"));
        var machineNames = string.Join(", ", plan.PlanMachines.Select(m => m.Machine != null ? m.Machine.Name : "Makine"));
        var statusLabel = GetPlanStatusLabel(plan.Status);
        var desc = plan.Description ?? "Yok";
        
        return plan.PlanCode + " (" + statusLabel + ")\n" +
               "Urun: " + productNames + "\n" +
               "Makine: " + machineNames + "\n" +
               "Miktar: " + plan.TargetQuantity + " Adet\n" +
               "Tahmini Bitis: " + plan.EstimatedEndDate.ToString("dd.MM.yyyy HH:mm") + "\n" +
               "Aciklama: " + desc;
    }

    private string GetTurkishDayName(DayOfWeek day) => day switch
    {
        DayOfWeek.Monday => "Pazartesi",
        DayOfWeek.Tuesday => "Salı",
        DayOfWeek.Wednesday => "Çarşamba",
        DayOfWeek.Thursday => "Perşembe",
        DayOfWeek.Friday => "Cuma",
        DayOfWeek.Saturday => "Cumartesi",
        DayOfWeek.Sunday => "Pazar",
        _ => ""
    };

    private void HandleDragStart(ProductionPlan demand)
    {
        draggedDemandPlan = demand;
    }

    private void HandleDragEnd()
    {
    }

    private async Task HandleDrop(DateTime day, int hour)
    {
        if (draggedDemandPlan == null) return;

        var targetStart = day.Date.AddHours(hour);
        var currentHourStart = DateTime.Now.Date.AddHours(DateTime.Now.Hour);
        if (targetStart < currentHourStart)
        {
            errorMessage = "Geçmiş zamanlı planlama yapılamaz.";
            StateHasChanged();
            return;
        }

        try
        {
            var product = draggedDemandPlan.PlanProducts.FirstOrDefault()?.Product;
            if (product == null)
            {
                errorMessage = "Talebe ait ürün bulunamadı.";
                return;
            }

            // Set up modal states for scheduling from demand
            isCreatingDemand = false;
            isEditingDemand = false;
            isEditing = false;
            isPlanningFromDemand = true;
            editingPlanId = null;
            planCode = $"PLN-{draggedDemandPlan.PlanCode.Replace("DEM-", "")}";
            description = draggedDemandPlan.Description;
            targetQuantity = draggedDemandPlan.TargetQuantity;
            plannedStartDate = day.Date.AddHours(hour);
            plannedEndDate = day.Date.AddHours(hour + 1);
            
            selectedProductIds = new List<int> { product.Id };
            selectedMachineIds = new List<int>(); // User will select in the modal
            
            errorMessage = null;
            showModal = true;
            StateHasChanged();
        }
        catch (Exception ex)
        {
            errorMessage = $"Sürükle-bırak sırasında bir hata oluştu: {ex.Message}";
            draggedDemandPlan = null;
        }
    }

    private async Task AddUnplannedDemand()
    {
        if (newDemandProductId == 0 || newDemandQuantity <= 0) return;
        var product = productsList.FirstOrDefault(p => p.Id == newDemandProductId);
        if (product == null) return;

        try
        {
            var pCode = $"DEM-{product.ProductCode}-{DateTime.Now:yyyyMMdd}-{new Random().Next(100, 999)}";
            var plan = new ProductionPlan
            {
                PlanCode = pCode,
                Description = "Manuel eklenen talep",
                PlannedStartDate = DateTime.MinValue,
                PlannedEndDate = DateTime.MinValue,
                Status = ProductionPlanStatus.Demand,
                TargetQuantity = newDemandQuantity,
                CreatedDate = DateTime.Now,
                UpdatedDate = DateTime.Now
            };

            plan.PlanProducts.Add(new ProductionPlanProduct
            {
                Product = product,
                CreatedDate = DateTime.Now,
                UpdatedDate = DateTime.Now
            });

            await ProductionPlanService.SaveProductionPlanAsync(plan);

            newDemandProductId = 0;
            newDemandQuantity = 1000;
            await LoadData();
        }
        catch (Exception ex)
        {
            errorMessage = $"Talep havuzuna eklenirken hata oluştu: {ex.Message}";
        }
     }

    private int GetHourlyCapacityForMachine(Machine machine, Product product)
    {
        double capacity = 0;
        if (machine is CoilWindingMachine cwm)
        {
            var originalProduct = cwm.CurrentProduct;
            cwm.CurrentProduct = product;
            var speed = cwm.CalculateOptimalSpeed(SpeedStrategyFactory);
            cwm.CurrentProduct = originalProduct;
            capacity = speed > 0 ? speed * 60 : 50;
        }
        else
        {
            capacity = 30;
        }
        return (int)capacity;
    }

    private async Task AutoScheduleDemand(ProductionPlan demand)
    {
        var product = demand.PlanProducts.FirstOrDefault()?.Product;
        if (product == null)
        {
            errorMessage = "Talebe ait ürün bulunamadı.";
            return;
        }

        isSaving = true;
        errorMessage = null;
        successMessage = null;

        try
        {
            int remainingQty = demand.TargetQuantity;
            var now = DateTime.Now;
            var searchTime = new DateTime(now.Year, now.Month, now.Day, now.Hour, 0, 0).AddHours(1);

            int safetyCounter = 0;
            var createdPlansCount = 0;
            var placementDetails = new List<string>();

            // Load fresh plans from DB to prevent overlapping
            var allPlans = await ProductionPlanService.GetAllProductionPlansAsync();
            var activePlans = allPlans.Where(p => p.Status != ProductionPlanStatus.Demand).ToList();

            while (remainingQty > 0 && safetyCounter < 720) // Search up to 30 days
            {
                var slotStart = searchTime;
                var slotEnd = searchTime.AddHours(1);

                // Find busy machines in this 1-hour slot
                var plansInSlot = activePlans
                    .Where(p => p.PlannedStartDate < slotEnd && p.PlannedEndDate > slotStart)
                    .ToList();

                var busyMachineIds = plansInSlot
                    .SelectMany(p => p.PlanMachines.Select(pm => pm.Machine?.Id))
                    .Where(id => id.HasValue)
                    .Select(id => id!.Value)
                    .ToHashSet();

                // Find free machines in this slot that are not in maintenance/malfunction
                var freeMachines = machinesList
                    .Where(m => !busyMachineIds.Contains(m.Id) && m.Status != MachineStatus.Maintenance && m.Status != MachineStatus.Malfunction)
                    .ToList();

                if (freeMachines.Any())
                {
                    foreach (var machine in freeMachines)
                    {
                        if (remainingQty <= 0) break;

                        int hourlyCapacity = GetHourlyCapacityForMachine(machine, product);
                        int planQty = Math.Min(remainingQty, hourlyCapacity);

                        var plan = new ProductionPlan
                        {
                            PlanCode = $"PLN-{demand.PlanCode.Replace("DEM-", "")}-{searchTime:yyyyMMddHH}",
                            Description = $"Otomatik akıllı zamanlama ({demand.PlanCode})",
                            PlannedStartDate = slotStart,
                            PlannedEndDate = slotEnd,
                            Status = ProductionPlanStatus.Scheduled,
                            TargetQuantity = planQty,
                            CreatedDate = DateTime.Now,
                            UpdatedDate = DateTime.Now
                        };

                        plan.PlanProducts.Add(new ProductionPlanProduct
                        {
                            Product = product,
                            CreatedDate = DateTime.Now,
                            UpdatedDate = DateTime.Now
                        });

                        plan.PlanMachines.Add(new ProductionPlanMachine
                        {
                            Machine = machine,
                            CreatedDate = DateTime.Now,
                            UpdatedDate = DateTime.Now
                        });

                        await ProductionPlanService.SaveProductionPlanAsync(plan);
                        
                        // Add to our list of active plans in-memory so next iterations of the loop know this machine is now busy
                        activePlans.Add(plan);

                        placementDetails.Add($"{slotStart:dd.MM.yyyy HH:00} ({machine.Name})");
                        remainingQty -= planQty;
                        createdPlansCount++;
                    }
                }

                searchTime = searchTime.AddHours(1);
                safetyCounter++;
            }

            if (remainingQty > 0)
            {
                errorMessage = $"Talep kısmen planlanabildi. Kalan miktar: {remainingQty} Adet. Lütfen kapasiteyi veya makineleri kontrol edin.";
            }

            if (placementDetails.Any())
            {
                successMessage = $"'{demand.PlanCode}' kodlu talep başarıyla zamanlandı! Atanan slotlar: {string.Join(", ", placementDetails)}";
            }

            // Remove the original demand if it is fully planned, or update its target quantity if partially planned!
            if (remainingQty <= 0)
            {
                await ProductionPlanService.DeleteProductionPlanAsync(demand.Id);
            }
            else
            {
                demand.TargetQuantity = remainingQty;
                await ProductionPlanService.SaveProductionPlanAsync(demand);
            }

            // Refresh the screen
            await LoadData();
            StateHasChanged();
            
            // Notify other users/circuits
            PlanEventService.NotifyPlanStatusChanged(0);
        }
        catch (Exception ex)
        {
            errorMessage = $"Otomatik planlama sırasında hata oluştu: {ex.Message}";
        }
        finally
        {
            isSaving = false;
        }
    }

    private async Task HandlePlanStatusChanged(int planId)
    {
        await InvokeAsync(async () =>
        {
            await LoadData();
            StateHasChanged();
        });
    }

    public void Dispose()
    {
        PlanEventService.OnPlanStatusChanged -= HandlePlanStatusChanged;
    }

